+export interface ForecastHour {
+  time: Date;
+  temperature: number;
+  precipitation: number;
+}
+
+export function renderForecast(hours: ForecastHour[]): HTMLElement {
+  const panel = document.createElement("section");
+  panel.className = "forecast";
+
+  for (const hour of hours) {
+    const cell = document.createElement("div");
+    cell.className = "forecast-hour";
+    cell.innerHTML = `
+      <time>${hour.time.getHours()}:00</time>
+      <strong>${Math.round(hour.temperature)}°</strong>
+      <span class="chance">${Math.round(hour.precipitation * 100)}%</span>
+    `;
+    panel.append(cell);
+  }
+
+  return panel;
+}

